    24	
    25	    public void createReservation(Context ctx) {
    26	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
    27	
    28	        if (request.roomNumber() == null || request.guestName() == null || request.guestEmail() == null ||
    29	            request.guestCpf() == null || request.checkIn() == null || request.checkOut() == null ||
    30	            request.guests() == null || request.ratePlan() == null) {
    31	            throw new ReservationService.InvalidRequestException("Missing required fields");
    32	        }
    33	
    34	        LocalDate checkIn = parseDate(request.checkIn());
    35	        LocalDate checkOut = parseDate(request.checkOut());
    36	
    37	        Reservation reservation = reservationService.createReservation(
    38	            request.roomNumber(),
    39	            request.guestName(),
    40	            request.guestEmail(),
    41	            request.guestCpf(),
    42	            checkIn,
    43	            checkOut,
    44	            request.guests(),
    45	            request.ratePlan()
    46	        );
    47	
    48	        ctx.status(201).json(mapReservation(reservation));
    49	    }
