     9	public class DocumentFormatter {
    10	    private static final Locale BRAZIL = Locale.of("pt", "BR");
    11	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    12	    private static final NumberFormat MONEY_FORMAT = NumberFormat.getCurrencyInstance(BRAZIL);
    13	
    14	    public static String formatDate(LocalDate date) {
    15	        return date.format(DATE_FORMAT);
    16	    }
    17	
    18	    public static String formatMoney(BigDecimal amount) {
    19	        return MONEY_FORMAT.format(amount);
    20	    }
    21	
    22	    public static String formatCpf(String cpf) {
    23	        if (cpf.length() != 11) {
    24	            return cpf;
    25	        }
    26	        return cpf.substring(0, 3) + "." +
    27	               cpf.substring(3, 6) + "." +
    28	               cpf.substring(6, 9) + "-" +
    29	               cpf.substring(9, 11);
    30	    }
