    32	    public static String formatReceipt(Reservation reservation, RoomType roomType) {
    33	        StringBuilder sb = new StringBuilder();
    34	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    35	        sb.append("Hóspede: ").append(reservation.getGuestName())
    36	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")").append("\n");
    37	        sb.append("Quarto: ").append(reservation.getRoomNumber())
    38	          .append(" (").append(roomType).append(")").append("\n");
    39	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
    40	          .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
    41	          .append(" | ").append(reservation.getNights())
    42	          .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    43	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
    44	
    45	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    46	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
    47	        }
    48	
    49	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
    50	
    51	        return sb.toString();
    52	    }
