    16	    private final RatePlan ratePlan;
    17	    private final int nights;
    18	    private final BigDecimal subtotal;
    19	    private final BigDecimal discount;
    20	    private final BigDecimal total;
    21	
    22	    private ReservationStatus status;
    23	    private BigDecimal amountPaid;
    24	    private BigDecimal refund;
    25	
    26	    public Reservation(Long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
    27	                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
    28	                      BigDecimal nightlyRate) {
    29	        this.id = id;
    30	        this.roomNumber = roomNumber;
    31	        this.guestName = guestName;
    32	        this.guestEmail = guestEmail;
    33	        this.guestCpf = guestCpf;
    34	        this.checkIn = checkIn;
    35	        this.checkOut = checkOut;
    36	        this.guests = guests;
    37	        this.ratePlan = ratePlan;
    38	
    39	        this.nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    40	        this.subtotal = PriceCalculator.calculateSubtotal(nightlyRate, checkIn, checkOut);
    41	        this.discount = PriceCalculator.calculateDiscount(this.subtotal, ratePlan);
    42	        this.total = PriceCalculator.calculateTotal(this.subtotal, this.discount);
    43	
    44	        this.status = ReservationStatus.PENDING;
    45	        this.amountPaid = BigDecimal.ZERO;
    46	        this.refund = null;
    47	    }
    48	
    49	    public Reservation(Long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
    50	                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
    51	                      int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total,
    52	                      ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
    53	        this.id = id;
    54	        this.roomNumber = roomNumber;
    55	        this.guestName = guestName;
    56	        this.guestEmail = guestEmail;
    57	        this.guestCpf = guestCpf;
    58	        this.checkIn = checkIn;
    59	        this.checkOut = checkOut;
    60	        this.guests = guests;
    61	        this.ratePlan = ratePlan;
    62	        this.nights = nights;
    63	        this.subtotal = subtotal;
    64	        this.discount = discount;
    65	        this.total = total;
    66	        this.status = status;
    67	        this.amountPaid = amountPaid;
    68	        this.refund = refund;
    69	    }
    70	
    71	    public void confirm() {
    72	        if (status != ReservationStatus.PENDING) {
    73	            throw new IllegalStateException("Only pending reservations can be confirmed");
    74	        }
    75	        this.status = ReservationStatus.CONFIRMED;
    76	        this.amountPaid = this.total;
    77	    }
    78	
    79	    public void checkIn() {
    80	        if (status != ReservationStatus.CONFIRMED) {
    81	            throw new IllegalStateException("Only confirmed reservations can be checked in");
    82	        }
    83	        this.status = ReservationStatus.CHECKED_IN;
    84	    }
    85	
    86	    public void checkOut() {
    87	        if (status != ReservationStatus.CHECKED_IN) {
    88	            throw new IllegalStateException("Only checked-in reservations can be checked out");
    89	        }
    90	        this.status = ReservationStatus.CHECKED_OUT;
    91	    }
    92	
    93	    public void cancel() {
    94	        if (status == ReservationStatus.CHECKED_IN || status == ReservationStatus.CHECKED_OUT) {
    95	            throw new IllegalStateException("Cannot cancel a reservation after check-in");
    96	        }
    97	        if (status == ReservationStatus.CANCELLED) {
    98	            throw new IllegalStateException("Reservation is already cancelled");
    99	        }
   100	
   101	        this.status = ReservationStatus.CANCELLED;
   102	
   103	        if (ratePlan == RatePlan.STANDARD) {
   104	            this.refund = this.amountPaid;
   105	        } else {
   106	            this.refund = BigDecimal.ZERO;
   107	        }
   108	    }
   109	
   110	    public boolean isPaid() {
   111	        return status == ReservationStatus.CONFIRMED
   112	            || status == ReservationStatus.CHECKED_IN
   113	            || status == ReservationStatus.CHECKED_OUT;
