     1	package com.pousadamarealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PriceCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final RoundingMode ROUNDING = RoundingMode.HALF_EVEN;
    11	
    12	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
    13	        BigDecimal price = baseRate;
    14	        if (isHighSeason(night)) {
    15	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
    16	        }
    17	        return price.setScale(2, ROUNDING);
    18	    }
    19	
    20	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    21	        BigDecimal subtotal = BigDecimal.ZERO;
    22	        LocalDate current = checkIn;
    23	        while (current.isBefore(checkOut)) {
    24	            subtotal = subtotal.add(calculateNightPrice(baseRate, current));
    25	            current = current.plusDays(1);
    26	        }
    27	        return subtotal.setScale(2, ROUNDING);
    28	    }
    29	
    30	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    31	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate());
    32	        return discount.setScale(2, ROUNDING);
    33	    }
    34	
    35	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    36	        return subtotal.subtract(discount).setScale(2, ROUNDING);
    37	    }
    38	
    39	    private static boolean isHighSeason(LocalDate date) {
    40	        Month month = date.getMonth();
    41	        int day = date.getDayOfMonth();
    42	
    43	        if (month == Month.JULY) {
    44	            return true;
    45	        }
    46	
    47	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    48	            return true;
    49	        }
    50	
    51	        if (month == Month.DECEMBER && day >= 15) {
    52	            return true;
    53	        }
    54	
    55	        return false;
    56	    }
    57	}
