    28	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
    29	                                        LocalDate checkIn, LocalDate checkOut, int guests, String ratePlanStr) {
    30	
    31	        Room room = roomRepository.findByNumber(roomNumber)
    32	            .orElseThrow(() -> new RoomNotFoundException("Room not found: " + roomNumber));
    33	
    34	        if (guests > room.getCapacity()) {
    35	            throw new CapacityExceededException("Room capacity exceeded");
    36	        }
    37	
    38	        if (guests < 1) {
    39	            throw new InvalidRequestException("At least one guest is required");
    40	        }
    41	
    42	        if (!checkOut.isAfter(checkIn)) {
    43	            throw new InvalidRequestException("Check-out must be after check-in");
    44	        }
    45	
    46	        List<Reservation> conflicting = reservationRepository.findByRoomAndPeriod(roomNumber, checkIn, checkOut);
    47	        if (!conflicting.isEmpty()) {
    48	            throw new RoomUnavailableException("Room is not available for the selected dates");
    49	        }
    50	
    51	        Reservation reservation = new Reservation(
    52	            null, roomNumber, guestName, guestEmail, guestCpf,
    53	            checkIn, checkOut, guests,
    54	            parseRatePlan(ratePlanStr),
    55	            room.getNightlyRate()
    56	        );
    57	
    58	        return reservationRepository.save(reservation);
    59	    }
